    return off
  end
  hdr_arp:add(f_arp_proto_addr_len, buf(math.floor(off / 8), math.floor((off % 8 + 8 + 7) / 8)), buf():bitfield(off, 8))
  off = off + 8
  if off + 16 > avail then
